head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


hour = 0;
minute = 0;
second = 0;
timer;
firstTimer = true;
$(document).ready(function() {
    // 시간초기화
    scwin.initTime();

    // 타이머 시작
    scwin.startTimer();
    // 이벤트 바인딩
    //$("#btn_extn").on("click", restartTimer);

});






/**
 * 타이머 시작
 */
/**
 * @method
 * @name startTimer
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.startTimer = function() {
    scwin.timer = setInterval(function() {
        if (scwin.firstTimer) {
            scwin.firstTimer = false;
        }

        // 2. 카운트다운 계산
        if (scwin.hour > 0 && scwin.minute == 0) {
            scwin.hour = scwin.hour - 1;
            scwin.minute = 60;
        }

        // 세션종료5분전 알림
        if (scwin.hour == 0 && scwin.minute == 5 && scwin.second == 0) {
            $('#divTimeOut').removeClass('pop_wrap');
            $('#divTimeOutBack').removeClass('pop_wrap');
        }
        // 자동로그아웃처리
        else if (scwin.hour == 0 && scwin.minute == 0 && scwin.second == 0) {
            clearInterval(scwin.timer);
            location.href = "/main/login.do?method=timeOut";
        }
        if (scwin.minute > 0 && scwin.second == 0) {
            scwin.minute = scwin.minute - 1;
            scwin.second = 60;
        }
        scwin.second = scwin.second - 1;

        // 30초마다 서버로 request를 보내 세션이 끊기지 않게 한다.
        if (scwin.second == 0 || scwin.second == 30) {
            scwin.req4sessionExtn();
        }

        // 3. 분/초 텍스트 셋팅
        //$("#areaSessionTimer").text(minute + ":" + ((second+"").length==1?'0'+second:second));

        //  화면상단
        $("#areaSessionTimer").html(" " + scwin.hour + ":" + scwin.minute + ":" + ((scwin.second + "").length == 1 ? '0' + scwin.second : scwin.second));

        // 연장pop-up
        $("#auto_sec").text(scwin.hour + ":" + scwin.minute + ":" + ((scwin.second + "").length == 1 ? '0' + scwin.second : scwin.second));
    }, 1000);
};





/**
 * web.xml 에 Sessio timeout을 2분으로 해놨음.Session을 끊기지 않게 하려고 빈 request를 하나 날린다. 
 */
/**
 * @method
 * @name req4sessionExtn
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.req4sessionExtn = function() {
    $.ajax({
        type: "POST",
        url: "/main/login.do",
        data: "method=extensionSessionTime",
        success: function(data) {
            eval("var result = " + data);
            //			var result = data;

            //alert(result.logoutYn);

            if (result.logoutYn == 'Y') {
                location.href = "/main/login.do?method=logoutBySameCon";
            } else if (result.unusualYn == 'Y') {
                location.href = "/main/login.do?method=logoutByUnusualCon";
            }
        }
    });
};







/**
 * 타이머 재시작(세션 연장 시)
 */
/**
 * @method
 * @name restartTimer
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.restartTimer = function() {
    $('#divTimeOut').addClass('pop_wrap');
    $('#divTimeOutBack').addClass('pop_wrap');
    clearInterval(scwin.timer);
    scwin.initTime();
    scwin.startTimer();
};
/**
 * @method
 * @name initTime
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.initTime = function() {
    /*
    //local
    hour = 0;
    minute = 5;
    second = 10;
    */

    //개발
    scwin.hour = 1;
    scwin.minute = 59;
    scwin.second = 60;
    /*
    //운영
    hour = 0;
    minute = 29;
    second = 60;
    */

};
